// Parts rendered both inside and outside a critical root: they stay critical everywhere, so a pack styles them through tokens only. A pin, not a rule.
export const POPUPS_SHARED_TOKENS_ONLY: string[] = ['pattern-alert-body', 'pattern-alert-head', 'pattern-alert-note', 'pattern-alert-stack', 'pattern-warn-actions', 'pattern-warn-detail',
    'pattern-warn-headline', 'pattern-warn-mark', 'pattern-warn-root']

export const POPUPS_CRITICAL: string[] = [...new Set([...POPUPS_NAMED_CRITICAL, ...POPUPS_CRITICAL_CLOSURE])]
// The parts a pack may style freely: every literal part that is neither critical nor reach.
export const POPUPS_SAFE: string[] = POPUPS_PARTS.filter((name) => !POPUPS_CRITICAL.includes(name) && !POPUPS_REACH.includes(name))

/**
 * The registry the applied popups area is judged under. It declares no tokens, minimums, maximums or surfaces: popups.css sets no tokens (Rule SCOPE
 * refuses every custom property there), and effective() adds chat's critical and escape-route names, so a popups sheet can never name them.
 * A stylesheet whose `:root` or `html` entry sets `color-scheme` to light or dark is still admitted; the colour overlay then carries
 * that declaration (known limitation).
 */
export const POPUPS_REGISTRY: RegistryInput = { critical: POPUPS_CRITICAL, safe: POPUPS_SAFE, reach: POPUPS_REACH, controls: POPUPS_REACH, strictSafe: true, partRequired: true }

export const lintPopups = (css: string, name = ''): LintResult => lintPack(css, name, POPUPS_REGISTRY)

const POPUPS_PART_SET: ReadonlySet<string> = new Set(POPUPS_PARTS)

/** Whether a popups stylesheet may name this part. */
export const isPopupsPart = (name: string): boolean => POPUPS_PART_SET.has(name)
